const pilares = {
  1: { clave: 'QUE_ES', nombre: 'Qué es (educar)', descripcion: 'Explica qué es Kubika y cómo conecta el ERP con el resto de los sistemas usando IA. Tono educativo, sin asumir que el lector ya conoce el producto.' },
  2: { clave: 'POR_QUE', nombre: 'Por qué (dolor / valor)', descripcion: 'Habla del dolor real de sacar información del ERP a mano y del valor de recuperar ese tiempo. Tono empático, centrado en el problema del cliente.' },
  3: { clave: 'PRODUCTO', nombre: 'Producto (demo / plataforma)', descripcion: 'Muestra la plataforma en acción: una captura o video real de un reporte o cruce de datos resuelto por Kubika. NO se genera imagen con IA para este pilar: se usa una captura real.' },
  4: { clave: 'QUE_NO_ES', nombre: 'Qué no es (diferenciación)', descripcion: 'Aclara qué NO es Kubika (no es ERP, no es chatbot, no es proyecto de TI eterno, no promete magia). Tono seguro, sin arrogancia.' },
  5: { clave: 'PRUEBA', nombre: 'Prueba (caso / dato / cliente)', descripcion: 'Refuerza credibilidad con un dato de industria en términos cualitativos o un testimonio ya aprobado. Nunca inventar cifras o citas de clientes.' },
};

const hoy = new Date();
const diaSemana = hoy.getDay(); // 1=lunes ... 5=viernes
const pilar = pilares[diaSemana];

if (!pilar) {
  throw new Error('El workflow se disparó en un día no hábil (getDay()=' + diaSemana + '). Revisa el cron del Schedule Trigger y el timezone del workflow (debe ser America/Bogota).');
}

return [{
  json: {
    fecha: hoy.toISOString().slice(0, 10),
    dia_semana: diaSemana,
    pilar_clave: pilar.clave,
    pilar_nombre: pilar.nombre,
    pilar_descripcion: pilar.descripcion,
  }
}];

const pilarData = $('Seleccionar Pilar del Dia').first().json;
const historialItems = $input.all();
const historialReal = historialItems.filter(i => i.json && i.json.fecha);

const historialTexto = historialReal.length
  ? historialReal.slice(-10).map(i => `- [${i.json.fecha || ''}] (${i.json.pilar || ''}) ${i.json.hook || ''}`).join('\n')
    : 'Sin historial previo registrado todavia.';

const feedbackReciente = historialReal
  .filter(i => i.json.feedback && String(i.json.feedback).trim() !== '')
  .slice(-5)
  .map(i => `- [${i.json.fecha || ''}] ${i.json.feedback}`)
  .join('\n');

const feedbackTexto = feedbackReciente
  ? `\nFEEDBACK RECIENTE DEL EQUIPO (aplica estas correcciones y preferencias al escribir el post de hoy):\n${feedbackReciente}\n`
    : '';

const userPrompt = `PILAR DE HOY: ${pilarData.pilar_nombre} (${pilarData.pilar_clave})
DIA: ${pilarData.fecha}
DESCRIPCION DEL PILAR: ${pilarData.pilar_descripcion}

GANCHOS/TEMAS USADOS EN LOS ULTIMOS DIAS (evita repetir el mismo angulo o hook):
${historialTexto}
${feedbackTexto}
Escribe el post de LinkedIn de hoy para Kubika siguiendo el pilar y las reglas del system prompt. Devuelve solo el JSON.`;

return [{
    json: {
          ...pilarData,
          user_prompt: userPrompt,
    }
}];

const agentOutput = $json;
const post = agentOutput.output || agentOutput;
const requeridos = ['hook', 'cuerpo', 'cta', 'hashtags', 'prompt_imagen'];
for (const campo of requeridos) {
  if (!post[campo]) throw new Error(`Falta el campo "${campo}" en la respuesta de la IA`);
}

const pilarData = $('Preparar Contexto IA').first().json;
const hashtagsTexto = post.hashtags.map(h => h.startsWith('#') ? h : '#' + h).join(' ');
const textoCompleto = `${post.hook}\n\n${post.cuerpo}\n\n${post.cta}\n\n${hashtagsTexto}`;

return [{
  json: {
    ...pilarData,
    ...post,
    hashtags_texto: hashtagsTexto,
    texto_completo: textoCompleto,
  }
}];

const fondosPorPilar = {
    QUE_ES: '#EEE9FB',
    POR_QUE: '#15151F',
    QUE_NO_ES: '#EEE9FB',
    PRUEBA: '#15151F',
};
const textoPorPilar = {
    QUE_ES: '#15151F',
    POR_QUE: '#FFFFFF',
    QUE_NO_ES: '#15151F',
    PRUEBA: '#FFFFFF',
};

const fondo = fondosPorPilar[$json.pilar_clave] || '#EEE9FB';
const colorTexto = textoPorPilar[$json.pilar_clave] || '#15151F';
const acento = '#A8E0C8';

const titularCrudo = $json.hook || '';
const titular = titularCrudo.length > 90 ? titularCrudo.slice(0, 90) + '...' : titularCrudo;

const mascotaSvg = `<svg width="150" height="150" viewBox="0 0 150 150" style="position:absolute;bottom:70px;right:70px;">
  <defs>
      <radialGradient id="kuboBody" cx="35%" cy="28%" r="75%">
            <stop offset="0%" stop-color="#C9BAFF"/>
                  <stop offset="100%" stop-color="#7B5CFF"/>
                      </radialGradient>
                          <radialGradient id="kuboCore" cx="35%" cy="28%" r="75%">
                                <stop offset="0%" stop-color="#DFF7EB"/>
                                      <stop offset="100%" stop-color="#A8E0C8"/>
                                          </radialGradient>
                                              <filter id="kuboShadow" x="-50%" y="-50%" width="200%" height="200%">
                                                    <feDropShadow dx="0" dy="10" stdDeviation="10" flood-color="#15151F" flood-opacity="0.28"/>
                                                        </filter>
                                                          </defs>
                                                            <ellipse cx="75" cy="82" rx="58" ry="54" fill="url(#kuboBody)" filter="url(#kuboShadow)"/>
                                                              <circle cx="75" cy="72" r="26" fill="url(#kuboCore)"/>
                                                                <circle cx="46" cy="126" r="9" fill="#FF9430"/>
                                                                  <circle cx="104" cy="126" r="9" fill="#FF9430"/>
                                                                  </svg>`;

const html = `<div style="position:relative;width:1080px;height:1350px;background:${fondo};display:flex;flex-direction:column;justify-content:space-between;padding:96px;font-family:Inter,sans-serif;box-sizing:border-box;overflow:hidden;">
  <div style="width:14px;height:14px;border-radius:50%;background:radial-gradient(circle at 35% 30%, #D9F5E7, ${acento} 65%, #6BB99A 100%);box-shadow:0 3px 8px rgba(21,21,31,0.18);"></div>
    <div style="font-size:64px;font-weight:800;letter-spacing:-0.02em;color:${colorTexto};line-height:1.15;">${titular}</div>
      ${mascotaSvg}
        <div style="font-size:32px;font-weight:800;color:${colorTexto};">kubika<span style="color:${acento};">.</span></div>
        </div>`;

return [{ json: { ...$json, html_pieza: html } }];

const agentOutput = $input.first().json;
const parsed = agentOutput.output || agentOutput;
const original = $('Send message and wait for response').first().json;

return [{
    json: {
          ...original,
          texto_completo: parsed.texto_completo,
          imageUrl: parsed.imageUrl,
          feedback: parsed.feedback || ''
    }
}];

