const contexto = $('Preparar Contexto IA').first().json;
const serp = $json;

let tendencias = [];
if (serp.organic_results && Array.isArray(serp.organic_results)) {
    tendencias = serp.organic_results.slice(0, 5).map(r => r.title).filter(Boolean);
}

const tendenciasTexto = tendencias.length > 0
  ? '\n\nTendencias recientes relacionadas en LinkedIn (usa esto solo como inspiracion de enfoque/angulo, sin inventar datos ni citar fuentes):\n- ' + tendencias.join('\n- ')
    : '';

const userPromptFinal = (contexto.user_prompt || '') + tendenciasTexto;

return [{ json: { ...contexto, user_prompt: userPromptFinal } }];
